import io
import json
import math


def load_scores(text):
    scores = {}
    first_lines = {}

    for line_no, line in enumerate(io.StringIO(text), start=1):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"line {line_no}: invalid JSON: {exc.msg}"
            ) from exc

        if not isinstance(record, dict):
            raise ValueError(f"line {line_no}: expected object")

        record_id = record.get("id")
        if not isinstance(record_id, str) or not record_id.strip():
            raise ValueError(f"line {line_no}: invalid id")
        record_id = record_id.strip()

        score = record.get("score")
        if (
            isinstance(score, bool)
            or not isinstance(score, (int, float))
            or not math.isfinite(score)
        ):
            raise ValueError(f"line {line_no}: invalid score")

        if record_id in first_lines:
            raise ValueError(
                f"line {line_no}: duplicate id {record_id!r}; "
                f"first seen on line {first_lines[record_id]}"
            )

        first_lines[record_id] = line_no
        scores[record_id] = score

    return scores
```

解析、字段校验和重复检查各自有明确责任，出错时也不会只留下一句含糊的“读取失败”。

用普通断言覆盖成功、坏 JSON、布尔分数和重复编号即可：

```python
sample = '{"id":"a","score":2}\n\n{"id":"b","score":3.5}\n'
assert load_scores(sample) == {"a": 2, "b": 3.5}

cases = [
    ('{"id":"a","score":}\n', "line 1: invalid JSON"),
    ('{"id":"a","score":true}\n', "line 1: invalid score"),
    (
        '{"id":"a","score":1}\n{"id":"a","score":2}\n',
        "line 2: duplicate id 'a'; first seen on line 1",
    ),
]
for text, expected in cases:
    try:
        load_scores(text)
    except ValueError as exc:
        assert str(exc).startswith(expected)
    else:
        raise AssertionError(f"expected failure: {expected}")
```

成功样例已用 Python 标准库实测通过。完整回归时还应补数组顶层、空 `id` 和非有限分数；只证明干净输入能读，并不能证明校验真正站岗。
